kp = root / "knowledge.json"
k = json.loads(kp.read_text())
ids = {s[0] for s in S}
k["scenarios"] = [x for x in k["scenarios"] if x["id"] not in ids]
for sid, when, boosts, name, advice, tr in S:
    k["scenarios"].append({"id": sid, "name": name, "when": when, "boosts": boosts, "advice": advice})
kp.write_text(json.dumps(k, ensure_ascii=False, indent=1) + "\n")
for i, l in enumerate(L):
    p = root / "locales" / f"{l}.json"
    raw = p.read_text(); d = json.loads(raw)
    for sid, when, boosts, name, advice, tr in S:
        d["text"][name], d["text"][advice] = tr[i]
    p.write_text(json.dumps(d, ensure_ascii=False, indent=1 if raw.startswith('{\n "') else 2) + "\n")
print(len(S), "scenarios")
